#!/bin/bash
set -euo pipefail
app_name=''
app_uuid=''
while getopts ':i:n:s:' opt; do
 case "$opt" in i) app_uuid="$OPTARG" ;; n|s) app_name="$OPTARG" ;; *) exit 64 ;; esac
done
[[ "$(id -un)" == 'emprendeclaro' ]] || exit 77
[[ "$app_name" == 'emprendeclaro_release_v4' ]] || exit 64
[[ "$(pwd -P)" == '/home/emprendeclaro/apps/emprendeclaro_release_v4' ]] || exit 77
[[ ! -e index.html && ! -L index.html ]] || exit 73
installer_tmp=$(mktemp './.emprendeclaro-install.XXXXXXXX')
trap 'rm -f -- "$installer_tmp"' EXIT
